WITH gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM sessions), sessions_sessions AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT DATE_TRUNC('QUARTER', started_at) AS quarter_start, CASE WHEN session_id >= 7 THEN 'HIGH' ELSE 'LOW' END AS session_id_tier, SUM(new_group_flag) FILTER (WHERE country = 'DE') AS de_total_new_group_flag, APPROX_PERCENTILE(new_group_flag, 0.9) AS new_group_flag_p90, COUNT(CASE WHEN browser = 'Firefox' THEN 1 END) AS firefox_count FROM sessions_sessions GROUP BY DATE_TRUNC('QUARTER', started_at), CASE WHEN session_id >= 7 THEN 'HIGH' ELSE 'LOW' END ORDER BY new_group_flag_p90 DESC NULLS LAST;
